WITH customer_summary AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned, COUNT(*) AS order_count FROM orders WHERE status = 'SHIPPED' GROUP BY customer_id) SELECT c.id, c.is_active, cs.pct_returned, cs.order_count FROM customers c LEFT OUTER JOIN customer_summary cs ON c.id = cs.customer_id ORDER BY pct_returned DESC, order_count DESC
